contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: callerIsOwner toggles whether this contract (owner) makes the withdraw call
    // amount is used for withdraw(uint) and sendMoney; must be affordable by c for a non-reverting transfer
    function run(bool callerIsOwner, uint amount) public payable {
        require(address(this).balance >= 0); // no-op to allow payable

        // Ensure contract C has some balance by sending Ether to it via its receive()
        // We send 1 wei to increment depositsCount and increase address(c).balance.
        // Must ensure this contract has enough balance to fund the call.
        // Use a small fixed funding amount: 1 wei. Require we have at least 1 wei.
        require(address(this).balance >= 1 wei);
        // send 1 wei to C to exercise receive and increment depositsCount
        c.f{value: 1 wei}();

        // Read observables before calls
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        bool withdrewReverted;
        // If callerIsOwner is true, we (this contract) are the owner because the checker deployed C with this InvMutTest as msg.sender
        // So calling withdraw should succeed when callerIsOwner==true and revert when false (simulated by calling from another address is impossible here).
        // To simulate a non-owner call, we attempt to call withdraw via sendMoney to C which will execute onlyOwner check with msg.sender being C (not helpful).
        // Instead we check that withdraw and withdrawAll are callable by the owner (this contract). That is a meaningful invariant: owner can withdraw full balance.

        // Try withdrawAll as owner (this contract). It must NOT revert and after it address(this).balance increases by the previous contract balance.
        bool withdrawAllReverted = false;
        uint balBeforeThis = address(this).balance;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        uint balAfterThis = address(this).balance;
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule asserted:
        // If withdrawAll did not revert then it must have transferred all Ether out of c to this contract
        // (i.e., address(c).balance became 0) and this contract's balance increased by exactly the prior c balance.
        assert((withdrawAllReverted == true) || ((afterBalance == 0) && (balAfterThis == balBeforeThis + beforeBalance)));
    }

    // allow this contract to receive Ether when c.withdraw transfers to it
    receive() external payable {}
 }

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function
    // We take an amount to fund C via its receive() fallback by calling address(c).call{value: amount}("")
    // but since C has a receive() payable, sending plain value will invoke it and increment depositsCount.
    function run(uint fundAmount) public payable {
        // ensure this test contract has enough Ether to fund C
        require(address(this).balance >= fundAmount);

        // Fund C so it has a non-zero balance and depositsCount increments
        // Call C by sending plain Ether which triggers receive()
        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent);

        // Observe before-values
        uint beforeBalance = address(c).balance;
        uint balBeforeThis = address(this).balance;

        // Attempt withdrawAll as owner (this contract is the deployer/owner of C)
        bool withdrewReverted = false;
        try c.withdrawAll() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        uint afterBalance = address(c).balance;
        uint balAfterThis = address(this).balance;

        // General rule: if withdrawAll did not revert then it must have emptied C's balance
        // and this contract's balance increased by exactly the prior C balance.
        assert((withdrewReverted == true) || ((afterBalance == 0) && (balAfterThis == balBeforeThis + beforeBalance)));
    }

    // allow receiving Ether when c.withdraw transfers to this contract
    receive() external payable {}
}

contract InvMutTest {
