    constructor(C _c) { c = _c; }

    // single public test function
    // fundAmount will be sent to c via a plain call which should trigger C.receive()
    function run(uint fundAmount) public payable {
        // ensure this test contract has enough Ether to fund C
        require(address(this).balance >= fundAmount);

        // Read observables before the call
        uint beforeDeposits = c.depositsCount();
        uint beforeBalanceC = address(c).balance;

        // Perform the state-changing action: send Ether to C which invokes receive()
        (bool sent, ) = address(c).call{value: fundAmount}("");

        // Read observables after the call
        uint afterDeposits = c.depositsCount();
        uint afterBalanceC = address(c).balance;

        // General rule: if the low-level send to C succeeded (so receive executed) then depositsCount increased by exactly 1
        // and C's balance increased by exactly fundAmount.
        assert((sent == false) || ((afterDeposits == beforeDeposits + 1) && (afterBalanceC == beforeBalanceC + fundAmount)));
    }

    // allow receiving Ether if C sends back to this contract in some scenarios
    receive() external payable {}
}

