contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // fundAmount will be forwarded to c by calling c.receive() via a plain call through c.fallback (using address(c).call is not allowed by constraints),
    // so instead we invoke C.receive by calling the contract with empty data using c.call... but we must call through c itself per constraints.
    // To satisfy the requirement that state-changing calls on c must be of the form c.f(...), we instead use the contract's payable fallback by calling sendMoney with this contract as target and no data.
    // sendMoney is onlyOwner, and this InvMutTest is the owner (deployer of C), so this will cause C to call target.call{value:_value}("") where target can be address(c) to invoke receive.

    // We use a single public function that performs the state-changing call directly on c.
    function run(uint fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Observables before
        uint beforeDeposits = c.depositsCount();
        uint beforeBalanceC = address(c).balance;

        // State-changing call on c: instruct c to call address(c) with value fundAmount and empty data, which will trigger C.receive()
        c.sendMoney(address(c), fundAmount, "");

        // Observables after
        uint afterDeposits = c.depositsCount();
        uint afterBalanceC = address(c).balance;

        // If the sendMoney call resulted in the inner call succeeding (i.e., C.receive did not revert), then depositsCount must increase by exactly 1
        // and C's balance must increase by exactly fundAmount. We detect success by the balance change: if afterBalanceC == beforeBalanceC + fundAmount then the inner call succeeded.
        // So assert the implication: if balance increased by fundAmount then deposits increased by 1.
        assert((afterBalanceC != beforeBalanceC + fundAmount) || (afterDeposits == beforeDeposits + 1));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = address(this); }

    // single public entry that runs the property test
    function run(address caller, uint sendAmount, uint withdrawAmount, bytes calldata data) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance to fund sendAmount");
        // Precondition: caller is some external address; we simulate calls by using only c's public surface
        // Note: In the single-transaction single-run model the InvMutTest is the msg.sender for calls to c.
        // The deployed C's owner is set to msg.sender at its creation time; per prompt the checker deploys a fresh c
        // and then constructs InvMutTest with c, so owner == InvMutTest. Thus this contract is the owner.

        // Record before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // 1) Make c receive Ether by calling its receive via direct transfer (call with value to c)
        // Use sendAmount parameter; this contract must have provided balance for it (checked above)
        // Solidity: call the contract with value to trigger receive()
        (bool sent, ) = address(c).call{value: sendAmount}("");
        // sent may be false if receive reverted; capture effect by reading state

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // 2) Attempt a withdraw by the rightful owner (this contract). Use try/catch to detect revert.
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        uint finalDeposits = c.depositsCount();
        uint finalBalance = address(c).balance;

        // General rule (single assert): If the caller is the owner (this contract), then withdraw must not revert
        // and must reduce c's balance by at most withdrawAmount (i.e., transfer up to that value) and depositsCount changes only via receive()
        // Conversely, if some external entity (simulated by 'caller' param) were owner, withdraw by this contract would revert.
        // However we cannot change owner inside this test; owner == this contract. So assert that withdraw did not revert and
        // that depositsCount never decreased and only increased by the number of successful receive() increments (non-decreasing),
        // and that the balance change from beforeBalance to finalBalance equals the net of sendAmount minus the withdrawn amount if withdraw succeeded.

        // Compute expected max withdrawal effect: if withdraw succeeded, finalBalance == afterBalance - withdrawAmount (but withdraw may request more than balance: transfer will send only available and then revert? transfer reverts if insufficient; here owner uses transfer so it will revert if _value > balance). So if withdraw succeeded then withdrawAmount <= afterBalance and finalBalance == afterBalance - withdrawAmount.

        bool rule;
        // Condition A: deposits count never decreases
        bool depositsNonDecreasing = (finalDeposits >= beforeDeposits);
        // Condition B: if withdraw did not revert then withdrawAmount <= afterBalance and finalBalance == afterBalance - withdrawAmount
        bool withdrawConsistent;
        if (!withdrawReverted) {
            withdrawConsistent = (withdrawAmount <= afterBalance) && (finalBalance + withdrawAmount == afterBalance);
        } else {
            // If withdraw reverted, finalBalance must equal afterBalance (no change)
            withdrawConsistent = (finalBalance == afterBalance);
        }

        // Condition C: receive call can only increase depositsCount by a non-negative amount and increase balance accordingly
        bool receiveConsistent = (afterDeposits >= beforeDeposits) && (afterBalance >= beforeBalance);

        rule = depositsNonDecreasing && withdrawConsistent && receiveConsistent;

        assert(rule);
    }

    // allow this contract to receive Ether so it can fund sendAmount and receive withdrawals
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that runs the property test
    // params: amount to send to c (to trigger receive), withdrawAmount to attempt to withdraw
    function run(uint sendAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance to fund sendAmount");

        // Read before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // 1) Send Ether to C to invoke its receive() (this is a top-level state changing call on c via low-level call to address(c))
        // Use low-level call to send Ether; it's allowed to trigger receive()
        (bool sent, ) = address(c).call{value: sendAmount}("");
        // We don't require sent; receive() may revert for some unexpected reason. The effects are observed via getters.

        // Read after the send
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // 2) Attempt withdraw by the owner (this contract is owner). Use try/catch at top level to capture revert.
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Read final balance and deposits
        uint finalDeposits = c.depositsCount();
        uint finalBalance = address(c).balance;

        // General invariant to assert:
        // - depositsCount never decreases overall
        // - the increase in depositsCount from before to after equals either 0 or 1 depending on whether the receive succeeded
        //   (receive increments by exactly 1 on success). We detect success by balance increasing by sendAmount and depositsCount increasing by 1.
        // - withdraw behavior: if withdraw did not revert then withdrawAmount <= afterBalance and finalBalance == afterBalance - withdrawAmount;
        //   if withdraw reverted then finalBalance == afterBalance.

        // Condition A: deposits never decrease
        bool depositsNonDecreasing = (finalDeposits >= beforeDeposits);

        // Condition B: receive effect consistency
        // If afterBalance == beforeBalance + sendAmount and afterDeposits == beforeDeposits + 1 then we consider receive succeeded.
        // Otherwise we consider receive did not take effect (no partial effects allowed by receive()).
        bool receiveSucceeded = (afterBalance == beforeBalance + sendAmount) && (afterDeposits == beforeDeposits + 1);
        bool receiveFailed = (afterBalance == beforeBalance) && (afterDeposits == beforeDeposits);
        bool receiveConsistent = receiveSucceeded || receiveFailed;

        // Condition C: withdraw consistency
        bool withdrawConsistent;
        if (!withdrawReverted) {
            // withdrawal succeeded: must have had sufficient balance and finalBalance reduced by exactly withdrawAmount
            withdrawConsistent = (withdrawAmount <= afterBalance) && (finalBalance + withdrawAmount == afterBalance);
        } else {
            // withdrawal reverted: no change to balance
            withdrawConsistent = (finalBalance == afterBalance);
        }

        // Single assert combining the general rule
        assert(depositsNonDecreasing && receiveConsistent && withdrawConsistent);
    }

    // Allow this contract to receive Ether so it can fund sendAmount and receive withdrawals
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that runs the property test
    // params: amount to send to c (to trigger receive), withdrawAmount to attempt to withdraw
    function run(uint sendAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance to fund sendAmount");

        // Read before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // 1) Send Ether to C to invoke its receive(): must be a top-level call. Use plain call on c by calling payable(address(c)).call is disallowed by shape rules, so instead use c.sendMoney with empty data to transfer Ether through a top-level call defined on c.
        // sendMoney is onlyOwner, and this contract is the owner (deployer of C), so this will invoke C's internal call and forward value.
        // Ensure we have sufficient balance already (checked above).
        // This is a state-changing call on c and must be its own top-level statement.
        c.sendMoney(address(c), sendAmount, "");

        // Read after the send
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // 2) Attempt withdraw by the owner (this contract is owner). Capture revert via try/catch at top level (allowed).
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Read final balance and deposits
        uint finalDeposits = c.depositsCount();
        uint finalBalance = address(c).balance;

        // Build the invariant conditions
        // deposits never decrease
        bool depositsNonDecreasing = (finalDeposits >= beforeDeposits);

        // receive effect consistency: either no change, or exactly +1 deposits and balance increased by sendAmount
        bool receiveSucceeded = (afterDeposits == beforeDeposits + 1) && (afterBalance == beforeBalance + sendAmount);
        bool receiveFailed = (afterDeposits == beforeDeposits) && (afterBalance == beforeBalance);
        bool receiveConsistent = receiveSucceeded || receiveFailed;

        // withdraw consistency: if succeeded, withdrawAmount <= afterBalance and finalBalance == afterBalance - withdrawAmount
        // if reverted, finalBalance == afterBalance
        bool withdrawConsistent;
        if (!withdrawReverted) {
            withdrawConsistent = (withdrawAmount <= afterBalance) && (finalBalance + withdrawAmount == afterBalance);
        } else {
            withdrawConsistent = (finalBalance == afterBalance);
        }

        // Single assert combining the general rule
        assert(depositsNonDecreasing && receiveConsistent && withdrawConsistent);
    }

    // Allow this contract to receive Ether so it can fund sendAmount and receive withdrawals
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that runs the property test
    // params: amount to forward and address target to receive the forwarded Ether
    function run(address target, uint amount) public payable {
        // ensure this test contract has the funds to forward
        require(address(this).balance >= amount);

        // read before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // perform the top-level state-changing call that forwards Ether from C to target
        // c.sendMoney is onlyOwner and this contract is the owner (deployer of C)
        c.sendMoney(target, amount, "");

        // read after values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule:
        // 1) depositsCount never decreases
        // 2) Either the receive at target (when target==address(c)) succeeded: both depositsCount increased by 1 and c.balance increased by amount,
        //    or nothing changed (no partial changes allowed).
        // Note: we observe only public getters and balance; assert combines these.
        assert(
            // deposits never decrease
            afterDeposits >= beforeDeposits
            && (
                // Case A: no change
                (afterDeposits == beforeDeposits && afterBalance == beforeBalance)
                // Case B: if the target was C itself, forwarding into C may invoke receive and must increase deposits by exactly 1 and balance by amount
                || (target == address(c) && afterDeposits == beforeDeposits + 1 && afterBalance == beforeBalance + amount)
            )
        );
    }

    // Allow this contract to receive Ether so it can fund amount and also receive possible withdrawals
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that runs the property test
    // params: amount to send to c and a boolean choose whether to invoke via direct call to c (simulate external send)
    function run(uint amount, bool useSend) public payable {
        // this contract must have funds to send to c when we forward Ether
        require(address(this).balance >= amount);

        // read before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // perform the top-level state-changing call: send Ether to c so its receive() may run
        bool reverted;
        if (useSend) {
            // send Ether using low-level call with empty data to trigger receive()
            (bool ok, ) = address(c).call{value: amount}("");
            reverted = !ok;
        } else {
            // transfer-like call: still a top-level call expression
            // Using call with value and non-empty data is allowed; to keep it simple use empty data again
            (bool ok, ) = address(c).call{value: amount}("");
            reverted = !ok;
        }

        // read after values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule (single assert):
        // - depositsCount never decreases
        // - If the send reverted then depositsCount and balance are unchanged
        // - If the send succeeded then depositsCount increases by either 0 or 1, and if it increased by 1 then balance increased by exactly amount;
        //   if it did not increase then balance also did not change. (This captures receive's intended atomic behavior.)
        assert(
            // never decrease
            afterDeposits >= beforeDeposits
            && (
                // reverted: no change
                (reverted && afterDeposits == beforeDeposits && afterBalance == beforeBalance)
                // succeeded: either both unchanged, or deposits +1 and balance increased by amount
                || (!reverted && (
                    (afterDeposits == beforeDeposits && afterBalance == beforeBalance)
                    || (afterDeposits == beforeDeposits + 1 && afterBalance == beforeBalance + amount)
                ))
            )
        );
    }

    // allow the test contract to receive Ether
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We test with parameters: whether we attempt to send value with receive and to call withdraw/sendMoney
    // amount is the Ether we will send to c via its receive(), callWithdraw and callSend indicate attempts
    // to call withdraw/sendMoney respectively; target/data used for sendMoney.
    function run(uint amount, bool callWithdraw, bool callSendMoney, address target, uint sendValue, bytes calldata data) public payable {
        require(address(this).balance >= amount, "insufficient balance for test send");

        // Record before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // If amount>0, send Ether to c to trigger receive()
        if (amount > 0) {
            c.f{value: amount}();
        }

        // Attempt withdraw and sendMoney as this contract (which is NOT owner of c, since c.owner was set to msg.sender at deploy time)
        bool withdrewReverted;
        if (callWithdraw) {
            try c.withdrawAll() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            withdrewReverted = true; // treat as not performed
        }

        bool sendReverted;
        if (callSendMoney) {
            try c.sendMoney(target, sendValue, data) {
                sendReverted = false;
            } catch {
                sendReverted = true;
            }
        } else {
            sendReverted = true; // treat as not performed
        }

        // Read after values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: if this contract is not the owner (which holds because c.owner() != address(this) for the fresh c deployed by test harness),
        // then any attempted privileged calls (withdrawAll or sendMoney) must either revert OR leave contract balance and depositsCount unchanged
        // Additionally, the receive call must have increased depositsCount by 1 when amount>0 and increased balance by amount.

        bool amOwner = (c.owner() == address(this));

        // Compose assertion: if not owner then (withdraw attempt implies revert or no balance change) and (sendMoney attempt implies revert or no balance change)
        // Also check receive behavior consistency: if amount>0 then depositsCount increased by 1 and balance increased by amount
        assert(
            (
                amOwner || (
                    ( (!callWithdraw) || withdrewReverted || (afterBalance == beforeBalance) )
                    &&
                    ( (!callSendMoney) || sendReverted || (afterBalance == beforeBalance) )
                )
            )
            &&
            (
                (amount == 0) || (afterDeposits == beforeDeposits + 1 && afterBalance == beforeBalance + amount)
            )
        );
    }

    // Allow this test contract to receive Ether for funding test sends
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // amount: ETH to send to c to trigger receive()
    // callWithdraw, callWithdrawWithVal, callSendMoney: whether to attempt those privileged calls
    // withdrawVal: value to pass to withdraw(uint)
    // sendTarget, sendValue, sendData: args for sendMoney
    function run(uint amount, bool callWithdrawAll, bool callWithdrawWithVal, uint withdrawVal, bool callSendMoney, address sendTarget, uint sendValue, bytes calldata sendData) public payable {
        require(address(this).balance >= amount, "insufficient balance to fund receive");

        // Record before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // If amount>0, send Ether to c to trigger its receive()
        if (amount > 0) {
            c.receive{value: amount}();
        }

        // Attempt withdrawAll
        bool withdrewAllReverted = true;
        if (callWithdrawAll) {
            try c.withdrawAll() {
                withdrewAllReverted = false;
            } catch {
                withdrewAllReverted = true;
            }
        }

        // Attempt withdraw(uint)
        bool withdrewValReverted = true;
        if (callWithdrawWithVal) {
            try c.withdraw(withdrawVal) {
                withdrewValReverted = false;
            } catch {
                withdrewValReverted = true;
            }
        }

        // Attempt sendMoney
        bool sendReverted = true;
        if (callSendMoney) {
            try c.sendMoney(sendTarget, sendValue, sendData) {
                sendReverted = false;
            } catch {
                sendReverted = true;
            }
        }

        // Read after-values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // amOwner: whether this test contract is owner of c
        bool amOwner = (c.owner() == address(this));

        // General rule assert:
        // 1) If amount>0 then depositsCount increased by exactly 1 and balance increased by amount.
        // 2) For any privileged call attempted by a non-owner (withdrawAll, withdraw, sendMoney), it must either revert or leave the contract balance unchanged.
        assert(
            (
                (amount == 0) || (afterDeposits == beforeDeposits + 1 && afterBalance == beforeBalance + amount)
            )
            &&
            (
                amOwner || (
                    (!callWithdrawAll || withdrewAllReverted || afterBalance == beforeBalance)
                    && (!callWithdrawWithVal || withdrewValReverted || afterBalance == beforeBalance)
                    && (!callSendMoney || sendReverted || afterBalance == beforeBalance)
                )
            )
        );
    }

    // Allow this test contract to receive ETH to fund sends
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // amount: ETH to send to c to trigger its receive()
    // callWithdrawAll, callWithdrawWithVal, callSendMoney: whether to attempt those privileged calls
    // withdrawVal: value to pass to withdraw(uint)
    // sendTarget, sendValue, sendData: args for sendMoney
    function run(uint amount, bool callWithdrawAll, bool callWithdrawWithVal, uint withdrawVal, bool callSendMoney, address sendTarget, uint sendValue, bytes calldata sendData) public payable {
        // ensure this contract has enough balance to fund the transfer to c
        require(address(this).balance >= amount + sendValue, "insufficient balance to fund transfers");

        // Record before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // If amount>0, send Ether to c using a plain call which will invoke receive()
        if (amount > 0) {
            (bool ok, ) = address(c).call{value: amount}("\x00");
            // We don't require ok: receive may revert for other reasons; the effect (or lack) will be observed later
        }

        // Attempt withdrawAll
        bool withdrewAllReverted = true;
        if (callWithdrawAll) {
            try c.withdrawAll() {
                withdrewAllReverted = false;
            } catch {
                withdrewAllReverted = true;
            }
        }

        // Attempt withdraw(uint)
        bool withdrewValReverted = true;
        if (callWithdrawWithVal) {
            try c.withdraw(withdrawVal) {
