    // - fund: amount of wei to send into c via receive()
    // - withdrawAmount: amount to withdraw via withdraw(uint)
    // - doWithdrawAll: if true, call withdrawAll(), else call withdraw(withdrawAmount)
    function run(uint fund, uint withdrawAmount, bool doWithdrawAll) public payable {
        require(address(this).balance >= fund, "insufficient balance to fund");

        // initial observations
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // fund the contract by sending Ether to it (invokes receive)
        if (fund > 0) {
            // send Ether to c
            (bool ok,) = address(c).call{value: fund}("");
            require(ok, "funding call failed");
        }

        // observe after funding
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // funding should increase balance by fund and depositsCount by either 0 or fund-triggered increments
        // The receive function increments depositsCount exactly once per receive call, so if fund>0 then depositsCount should increase by at least 1.
        // However multiple receive semantics aren't provable here; we assert the basic invariant: balance increased by fund and depositsCount did not decrease.
        assert(afterBalance == beforeBalance + fund);
        assert(afterDeposits >= beforeDeposits);

        // Now attempt withdrawal (this contract is the owner because constructor of C set owner to msg.sender at deployment, and test harness deploys C with this contract as deployer)
        bool reverted;
        uint balanceBeforeWithdraw = address(this).balance;
        uint contractBalanceBeforeWithdraw = address(c).balance;

