            reverted = false;
        } catch {
            reverted = true;
        }

        uint contractBalanceAfterWithdraw = address(c).balance;
        uint balanceAfterWithdraw = address(this).balance;

        // If withdraw did not revert, then contract's balance must have decreased by exactly withdrawAmount (or by contractBalanceBeforeWithdraw if withdrawAmount > contractBalanceBeforeWithdraw, transfer reverts on insufficient funds so it would revert; thus successful withdraw implies contractBalanceBeforeWithdraw >= withdrawAmount)
        // Also caller (this) should have received that amount
        if (!reverted) {
