            assert(balanceAfterWithdraw == balanceBeforeWithdraw + withdrawAmount);
        } else {
            // If reverted, balances must be unchanged
            assert(contractBalanceAfterWithdraw == contractBalanceBeforeWithdraw);
            assert(balanceAfterWithdraw == balanceBeforeWithdraw);
