        // The rule: withdraw either succeeds (not reverted) iff contract had at least withdrawAmount and then balances moved accordingly, otherwise it reverts and balances unchanged.
        assert((!reverted && contractBalanceBeforeWithdraw >= withdrawAmount && contractBalanceAfterWithdraw + withdrawAmount == contractBalanceBeforeWithdraw && balanceAfterWithdraw == balanceBeforeWithdraw + withdrawAmount) || (reverted && contractBalanceAfterWithdraw == contractBalanceBeforeWithdraw && balanceAfterWithdraw == balanceBeforeWithdraw));
