            // This is a top-level state-changing call
            (bool ok, ) = address(c).call{value: sendAmount}("");
            // deposit might revert if require in receive fails; propagate that by requiring ok
            // but we don't require ok to allow exploring revert behavior; instead record
            // success by reading c.balance below
        }

        // Record c balance before attempts
        uint balBefore = address(c).balance;

        // Try withdraw by a potential non-owner: we must simulate calls from different callers.
        // We cannot change msg.sender for calls; however the InvMutTest contract is the deployer/owner of c.
        // To simulate a non-owner calling, we use c.sendMoney to instruct c to call a target (no ownership change),
        // which cannot change owner; thus to test non-owner attempts we attempt calls via c's public functions
        // but the checker environment calls run exactly once from an external EOA; we can instead check that
        // any attempt by the owner (this contract) to withdraw must either succeed or revert, but non-owners cannot be emulated.
        // Instead, we assert that if msg.sender of c getter owner is not this contract, then withdrawAll and withdraw revert and do not change balance.

        address ownerAddr = c.owner();

        // Attempt withdrawAll and withdraw from this contract (which is the deployer so should be owner)
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        uint balAfterWithdrawAll = address(c).balance;

        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        uint balAfterWithdraw = address(c).balance;

        // General rule to assert:
        // If the stored owner is not this contract, then any attempt by this contract to call withdrawAll or withdraw must revert and must not change the contract balance.
        // If the stored owner is this contract, then either withdrawAll/withdraw may succeed or revert, but in the success case the balance must not increase.
        bool ownerIsThis = (ownerAddr == address(this));

        assert(
            // Case A: owner is not this contract -> both calls by this contract reverted and balances unchanged
            ( !ownerIsThis && withdrewAllReverted && withdrewReverted && balAfterWithdrawAll == balBefore && balAfterWithdraw == balBefore )
            ||
            // Case B: owner is this contract -> if calls did not revert, balance cannot have increased (no Ether creation). We allow either revert or non-revert.
            ( ownerIsThis && 
                // withdrawAll: if did not revert, balance after <= before
                (withdrewAllReverted || balAfterWithdrawAll <= balBefore) &&
                // withdraw: if did not revert, balance after <= balAfterWithdrawAll
                (withdrewReverted || balAfterWithdraw <= balAfterWithdrawAll)
            )
        );
    }

